  if(action==='edd'){const c=s().compliance.find(x=>x.client_id===id);actionForm('Approve enhanced due diligence',area('reason','Partner conclusion and evidence *','',true),'edd_approve',{client_id:id,revision:c.revision});return;}
  if(action==='activate'||action==='finalize'){actionForm(action==='activate'?'Activate engagement':'Finalize engagement',`<p>${esc(projectName(id))}</p><p>The server will verify the required evidence and approval controls before changing the status.</p>`,action==='activate'?'engagement_activate':'engagement_finalize',{project_id:id},'Confirm');return;}
