  if(action==='leave-new'){actionForm('Request leave',select('leave_type','Leave type',['Annual','Sick','Study','Maternity / Paternity'],'Annual')+field('starts_on','First day',today(),'date','required')+field('ends_on','Last day',today(),'date','required')+area('reason','Reason *','',true)+'<p class="info full">Any overlap with 15 January–30 April requires Partner review. Working-day counts exclude weekends; public holidays and leave entitlement must be checked by the reviewer.</p>','leave_request');return;}
  if(action==='leave-review'){const l=s().leave.find(x=>x.leave_id===id);modal('Review leave',form(`<p>${esc(staffName(l.staff_id))} · ${shortDate(l.starts_on)} – ${shortDate(l.ends_on)}</p>`+select('status','Decision',['Approved','Rejected'],'Approved')+area('review_note','Review / cover arrangements *','',true)+check('capacity_acknowledged','I have checked fieldwork assignments and arranged cover')),f=>request({action:'leave_review',...val(f),leave_id:id,revision:l.revision,capacity_acknowledged:f.has('capacity_acknowledged')}));return;}
