  if(action==='credential-new'){actionForm('Add credential / CPD',select('credential_type','Type',['CPA paper','ICPAK membership','CPD','Degree','Induction'],'CPD')+field('description','Description *','','text','required')+select('status','Status',['In progress','Passed','Expired'],'Passed')+field('issue_date','Earned / issued',today(),'date','required')+field('expiry_date','Expiry (if applicable)','','date')+field('cpd_hours','CPD hours',0,'number','min="0" step="0.25"')+field('evidence_reference','Certificate / evidence reference *','','text','required'),'credential_add');return;}
  if(action==='credential-verify'){const c=s().credentials.find(x=>x.credential_id===id);actionForm('Verify credential',`<p>${esc(c.description)} · ${esc(c.evidence_reference)}</p>`,'credential_verify',{credential_id:id,revision:c.revision},'Confirm verified');return;}
  if(action==='roster'||action==='performance'){const opts=d().assignments.map(a=>[a.project_id+'|'+a.staff_id,projectName(a.project_id)+' · '+staffName(a.staff_id)]);modal(action==='roster'?'Schedule fieldwork':'Engagement feedback',form(select('assignment','Project team member',opts)+(action==='roster'?field('starts_on','From',today(),'date','required')+field('ends_on','Through',today(),'date','required')+field('allocation_percentage','Allocation %',100,'number','required min="1" max="100"'):field('technical_score','Technical knowledge · 1–5',3,'number','required min="1" max="5"')+field('punctuality_score','Punctuality · 1–5',3,'number','required min="1" max="5"')+field('workpaper_score','Working paper quality · 1–5',3,'number','required min="1" max="5"')+area('comments','Feedback *','',true))),f=>{const [project_id,staff_id]=String(f.get('assignment')).split('|');return request({action:action==='roster'?'roster_save':'performance_add',...val(f),project_id,staff_id});});return;}
